'use client';

import { useEffect, useMemo, useRef, useState, type CSSProperties, type FormEvent, type ReactNode } from 'react';
import {
  ArrowDownLeft, ArrowRight, ArrowUpRight, Bell, Briefcase, CalendarDays, Car,
  ChartNoAxesCombined, Check, CheckCircle2, ChevronLeft, ChevronRight,
  CircleAlert, Clapperboard, CreditCard, Download, Eye, EyeOff, Focus,
  GraduationCap, Heart, House, Info, LayoutDashboard, Leaf, Lightbulb,
  ListChecks, LoaderCircle, LogOut, Pencil, Plus, ReceiptText, Repeat, Search,
  Shapes, ShieldCheck, ShoppingBag, Sparkles, Tag as TagIcon, Tags, Target, Trash2,
  TrendingUp, Utensils, Wallet,
} from 'lucide-react';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Progress } from '@/components/ui/progress';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Sidebar, SidebarContent, SidebarFooter, SidebarHeader, SidebarMenu, SidebarMenuButton, SidebarMenuItem, SidebarProvider, SidebarTrigger, useSidebar } from '@/components/ui/sidebar';
import { Skeleton } from '@/components/ui/skeleton';
import { Switch } from '@/components/ui/switch';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Toaster } from '@/components/ui/sonner';
import { Area, AreaChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { EMPTY, addDays, addMonths, balances, brl, categories, colors, invoiceBalance, money, monthStats, today, type Account, type Budget, type Category, type Goal, type Recurrence, type State, type Tag, type Transaction } from '@/shared/finance';
import { loadState, logout as authLogout, mutate, type AuthUser } from './api';
import { demoState } from './demo';
import { toast } from 'sonner';
import Link from 'next/link';

const nav = [
  ['overview', 'Visão geral', LayoutDashboard],
  ['transactions', 'Lançamentos', ReceiptText],
  ['agenda', 'Agenda financeira', CalendarDays],
  ['accounts', 'Contas e cartões', Wallet],
  ['budgets', 'Orçamentos', ChartNoAxesCombined],
  ['goals', 'Minhas metas', Target],
  ['categories', 'Categorias e tags', Tags],
] as const;
const icons: Record<string, typeof Shapes> = {
  Alimentação: Utensils, Moradia: House, Transporte: Car, Saúde: Heart,
  Educação: GraduationCap, Lazer: Clapperboard, Compras: ShoppingBag,
  Assinaturas: Repeat, Salário: Briefcase, Freelance: Briefcase,
};
const incomeCategories = ['Salário', 'Freelance', 'Outros'];
const expenseCategories = categories.filter((category) => !incomeCategories.includes(category));
const frequencyLabels = { weekly: 'Toda semana', monthly: 'Todo mês', yearly: 'Todo ano' } as const;
type FormKind = 'transactions' | 'accounts' | 'budgets' | 'goals' | 'recurrences' | 'categories' | 'tags';
type Entity = Account | Transaction | Budget | Goal | Recurrence | Category | Tag;
type Editor = { kind: FormKind; id?: string; values: Record<string, string> };
type AgendaItem = { id: string; date: string; title: string; amount: number; type: 'expense' | 'income'; category: string; recurring: boolean; accountId: string };
type AlertItem = { id: string; title: string; detail: string; tone: 'warning' | 'positive' };
type OnboardingData = { accountName: string; accountKind: 'checking' | 'cash'; opening: string; income: string; goalName: string; goalTarget: string; goalDate: string };

const monthLabel = (month: string) => new Date(`${month}-15T12:00:00`).toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });
const shortDate = (date: string) => new Date(`${date}T12:00:00`).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' }).replace('.', '');
const categoryType = (category: string): 'expense' | 'income' => incomeCategories.includes(category) ? 'income' : 'expense';
const splitIds = (value: string) => value.split(',').map((part) => part.trim()).filter(Boolean);
const monthsUntil = (date: string) => Math.max(1, Math.ceil((new Date(`${date}T12:00:00Z`).getTime() - new Date(`${today()}T12:00:00Z`).getTime()) / (1000 * 60 * 60 * 24 * 30.4375)));

function Picker({ label, value, onChange, options, allowEmpty = false }: { label: string; value: string; onChange: (value: string) => void; options: { value: string; label: string }[]; allowEmpty?: boolean }) {
  const selectedValue = value || (allowEmpty ? '__empty__' : options[0]?.value ?? '');
  return <div className="field"><span>{label}</span><Select value={selectedValue} onValueChange={(next) => onChange(next === '__empty__' ? '' : next)}><SelectTrigger aria-label={label}><SelectValue placeholder="Selecione" /></SelectTrigger><SelectContent position="popper">{allowEmpty && <SelectItem value="__empty__">Nenhuma</SelectItem>}{options.map((option) => <SelectItem key={option.value} value={option.value}>{option.label}</SelectItem>)}</SelectContent></Select></div>;
}

function Empty({ title, text, action }: { title: string; text: string; action?: ReactNode }) {
  return <div className="empty"><div className="empty-icon"><Leaf size={26} /></div><h3>{title}</h3><p>{text}</p>{action}</div>;
}

function CategoryIcon({ category, color }: { category: string; color: string }) {
  const Icon = icons[category] ?? Shapes;
  return <span className="category-icon" style={{ background: `${color}17`, color }}><Icon size={18} /></span>;
}

function Navigation({ view, onNav, focus, setFocus, user, onLogout }: { view: string; onNav: (value: string) => void; focus: boolean; setFocus: (value: boolean) => void; user: AuthUser; onLogout: () => void }) {
  const { setOpenMobile } = useSidebar();
  const initials = user.name.trim().split(/\s+/).slice(0, 2).map((part) => part[0]).join('').toUpperCase();
  return <Sidebar className="app-sidebar">
    <SidebarHeader><Link href="/" className="brand"><span className="brand-icon"><Leaf size={24} /></span>clareza<span className="brand-dot">.</span></Link><span className="brand-caption">UM PASSO DE CADA VEZ</span></SidebarHeader>
    <SidebarContent><div className="nav-label">MEU DINHEIRO</div><SidebarMenu>{nav.map(([id, label, Icon]) => <SidebarMenuItem key={id}><SidebarMenuButton isActive={view === id} onClick={() => { onNav(id); setOpenMobile(false); }}><Icon /><span>{label}</span></SidebarMenuButton></SidebarMenuItem>)}</SidebarMenu><div className="focus-box"><div><Focus size={19} /><strong>Modo foco</strong><Switch aria-label="Ativar modo foco" checked={focus} onCheckedChange={setFocus} /></div><p>Só o essencial. No seu ritmo.</p></div></SidebarContent>
    <SidebarFooter><div className="sidebar-note"><Leaf size={20} /><p>Pequenos registros.<br /><strong>Grandes mudanças.</strong></p></div><div className="profile"><span className="avatar">{initials || 'EU'}</span><div><strong>{user.name}</strong><span>{user.email}</span></div><button type="button" className="profile-logout" onClick={onLogout} aria-label="Sair" title="Sair"><LogOut size={18} /></button></div></SidebarFooter>
  </Sidebar>;
}

export default function FinanceApp({ user, onLogout }: { user: AuthUser; onLogout: () => void }) {
  const [real, setReal] = useState<State>(EMPTY);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState('');
  const [demo, setDemo] = useState(false);
  const [view, setView] = useState('overview');
  const [month, setMonth] = useState(today().slice(0, 7));
  const [focus, setFocus] = useState(() => { try { return typeof window !== 'undefined' && localStorage.getItem('clareza-focus') === 'true'; } catch { return false; } });
  const [hidden, setHidden] = useState(() => { try { return typeof window !== 'undefined' && localStorage.getItem('clareza-hidden') === 'true'; } catch { return false; } });
  const [editor, setEditor] = useState<Editor | null>(null);
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState('');
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('all');
  const [quick, setQuick] = useState('');
  const [deletion, setDeletion] = useState<{ kind: FormKind; id: string; name: string } | null>(null);
  const [onboardingOpen, setOnboardingOpen] = useState(false);
  const [onboardingStep, setOnboardingStep] = useState(1);
  const [onboardingError, setOnboardingError] = useState('');
  const [onboarding, setOnboarding] = useState<OnboardingData>({ accountName: 'Conta principal', accountKind: 'checking', opening: '', income: '', goalName: '', goalTarget: '', goalDate: addMonths(today(), 6) });
  const firstLoad = useRef(true);

  async function refresh() {
    setLoadError('');
    try {
      const state = await loadState();
      setReal(state);
      if (firstLoad.current) {
        setDemo(state.accounts.length === 0 && state.transactions.length === 0);
        firstLoad.current = false;
      }
    } catch (error) {
      setLoadError(error instanceof Error ? error.message : 'Não foi possível carregar seus dados.');
    } finally { setLoading(false); }
  }

  // A leitura do estado é uma sincronização assíncrona necessária com a API.
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { void refresh(); }, []);
  async function signOut() { try { await authLogout(); onLogout(); } catch (error) { toast.error(error instanceof Error ? error.message : 'Não foi possível sair agora.'); } }
  const state = useMemo(() => demo ? demoState(month) : real, [demo, month, real]);
  const stats = useMemo(() => monthStats(state, month), [month, state]);
  const previousStats = useMemo(() => monthStats(state, addMonths(`${month}-01`, -1).slice(0, 7)), [month, state]);
  const balancesByAccount = balances(state);
  const cash = state.accounts.filter((account) => account.kind !== 'credit').reduce((sum, account) => sum + (balancesByAccount[account.id] ?? 0), 0);
  const cardDebt = state.accounts.filter((account) => account.kind === 'credit').reduce((sum, account) => sum + Math.max(0, -(balancesByAccount[account.id] ?? 0)), 0);
  const cashPending = state.transactions.filter((transaction) => transaction.type === 'expense' && transaction.status === 'pending' && state.accounts.find((account) => account.id === transaction.accountId)?.kind !== 'credit').reduce((sum, transaction) => sum + transaction.amount, 0);
  const available = cash - cardDebt - cashPending;
  const currentDate = today();
  const horizon = addDays(currentDate, 30);
  const categoryColor = (name: string) => state.categories.find((category) => category.name === name)?.color ?? colors[Math.max(0, categories.indexOf(name)) % colors.length];
  const topLevelCategories = (type: 'expense' | 'income') => [...(type === 'income' ? incomeCategories : expenseCategories).map((name) => ({ value: name, label: name })), ...state.categories.filter((category) => category.type === type && !category.parentId).map((category) => ({ value: category.name, label: category.name }))];
  const subcategoriesFor = (categoryName: string) => { const parent = state.categories.find((category) => category.name === categoryName && !category.parentId); return parent ? state.categories.filter((category) => category.parentId === parent.id).map((category) => ({ value: category.name, label: category.name })) : []; };
  const categoryData = Object.entries(stats.tx.filter((transaction) => transaction.type === 'expense').reduce<Record<string, number>>((result, transaction) => { result[transaction.category] = (result[transaction.category] ?? 0) + transaction.amount; return result; }, {})).map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value);
  const previousCategoryData = Object.entries(previousStats.tx.filter((transaction) => transaction.type === 'expense').reduce<Record<string, number>>((result, transaction) => { result[transaction.category] = (result[transaction.category] ?? 0) + transaction.amount; return result; }, {})).map(([name, value]) => ({ name, value }));
  const monthlyBudgets = state.budgets.filter((budget) => budget.month === month);
  const isPending = (transaction: Transaction) => transaction.type === 'expense' && state.accounts.find((account) => account.id === transaction.accountId)?.kind === 'credit' ? invoiceBalance(state, transaction.accountId, transaction.date.slice(0, 7)) > 0 : transaction.status === 'pending';
  const txSorted = [...stats.tx].filter((transaction) => (filter === 'all' || (filter === 'pending' && isPending(transaction)) || transaction.type === filter) && `${transaction.title} ${transaction.category} ${transaction.subcategory ?? ''}`.toLocaleLowerCase().includes(search.toLocaleLowerCase())).sort((a, b) => b.date.localeCompare(a.date));
  const agendaItems: AgendaItem[] = [...state.transactions.filter((transaction) => transaction.type !== 'transfer' && transaction.status === 'pending' && transaction.date <= horizon).map((transaction) => ({ id: `transaction-${transaction.id}`, date: transaction.date, title: transaction.title, amount: transaction.amount, type: transaction.type as 'expense' | 'income', category: transaction.category, recurring: Boolean(transaction.recurrenceId), accountId: transaction.accountId })), ...state.recurrences.filter((recurrence) => recurrence.active && recurrence.nextDate <= horizon).map((recurrence) => ({ id: `recurrence-${recurrence.id}`, date: recurrence.nextDate, title: recurrence.title, amount: recurrence.amount, type: recurrence.type, category: recurrence.category, recurring: true, accountId: recurrence.accountId }))].sort((a, b) => a.date.localeCompare(b.date));
  const alerts: AlertItem[] = useMemo(() => { const items: AlertItem[] = []; const overdue = state.transactions.filter((transaction) => transaction.type === 'expense' && transaction.status === 'pending' && transaction.date < currentDate); if (overdue.length) items.push({ id: 'overdue', title: `${overdue.length} compromisso${overdue.length > 1 ? 's' : ''} vencido${overdue.length > 1 ? 's' : ''}`, detail: 'Revise a agenda para evitar juros ou esquecimentos.', tone: 'warning' }); const near = agendaItems.filter((item) => item.date >= currentDate && item.date <= addDays(currentDate, 7)); if (near.length) items.push({ id: 'near', title: `${near.length} compromisso${near.length > 1 ? 's' : ''} nos próximos 7 dias`, detail: 'Você já pode se preparar para as próximas saídas.', tone: 'positive' }); monthlyBudgets.filter((budget) => (categoryData.find((category) => category.name === budget.category)?.value ?? 0) / budget.amount >= .8).slice(0, 2).forEach((budget) => { const spent = categoryData.find((category) => category.name === budget.category)?.value ?? 0; items.push({ id: `budget-${budget.id}`, title: `${budget.category} chegou a ${Math.round(spent / budget.amount * 100)}%`, detail: spent > budget.amount ? 'O limite já foi ultrapassado neste mês.' : 'Ainda dá para ajustar o ritmo dos próximos dias.', tone: spent > budget.amount ? 'warning' : 'positive' }); }); const overdueGoal = state.goals.find((goal) => goal.date < currentDate && goal.saved < goal.target); if (overdueGoal) items.push({ id: 'goal', title: `${overdueGoal.name} precisa de um novo plano`, detail: 'Atualize o prazo ou o valor guardado para continuar acompanhando.', tone: 'warning' }); return items.slice(0, 5); }, [agendaItems, categoryData, currentDate, monthlyBudgets, state.goals, state.transactions]);
  const insights = useMemo(() => { const result: { id: string; title: string; detail: string; icon: typeof TrendingUp }[] = []; const top = categoryData[0]; if (top) { const before = previousCategoryData.find((category) => category.name === top.name)?.value ?? 0; result.push({ id: 'top', title: `${top.name} é seu maior grupo de gastos`, detail: `${brl(top.value)} no mês. ${before ? `${Math.round((top.value - before) / before * 100)}% em relação ao mês anterior.` : 'Continue registrando para comparar sua evolução.'}`, icon: TrendingUp }); } const overBudget = monthlyBudgets.find((budget) => (categoryData.find((category) => category.name === budget.category)?.value ?? 0) > budget.amount); if (overBudget) result.push({ id: 'budget', title: `${overBudget.category} pede atenção`, detail: `Você passou ${brl((categoryData.find((category) => category.name === overBudget.category)?.value ?? 0) - overBudget.amount)} do limite planejado.`, icon: CircleAlert }); const recurringTotal = state.recurrences.filter((recurrence) => recurrence.active && recurrence.frequency === 'monthly' && recurrence.type === 'expense').reduce((sum, recurrence) => sum + recurrence.amount, 0); if (recurringTotal) result.push({ id: 'recurring', title: 'Seus compromissos fixos já estão mapeados', detail: `${brl(recurringTotal)} por mês em recorrências ativas.`, icon: Repeat }); if (!result.length) result.push({ id: 'start', title: 'Seu primeiro insight começa com um registro', detail: 'Quanto mais claro o histórico, melhor o Clareza consegue mostrar seus próximos passos.', icon: Lightbulb }); return result.slice(0, 3); }, [categoryData, monthlyBudgets, previousCategoryData, state.recurrences]);
  const chartData = Array.from({ length: new Date(Number(month.slice(0, 4)), Number(month.slice(5)), 0).getDate() }, (_, index) => { const date = `${month}-${String(index + 1).padStart(2, '0')}`; return { day: String(index + 1), income: stats.tx.filter((transaction) => transaction.date <= date && transaction.type === 'income').reduce((sum, transaction) => sum + transaction.amount, 0) / 100, expense: stats.tx.filter((transaction) => transaction.date <= date && transaction.type === 'expense').reduce((sum, transaction) => sum + transaction.amount, 0) / 100 }; });

  function displayMoney(value: number) { return hidden ? 'R$ •••••' : brl(value); }
  function preference(which: 'focus' | 'hidden', value: boolean) { if (which === 'focus') setFocus(value); else setHidden(value); try { localStorage.setItem(`clareza-${which}`, String(value)); } catch { /* preferências são opcionais */ } }
  function resetOperation() { setFormError(''); }
  function openEditor(kind: FormKind, record?: Entity, extra: Record<string, string> = {}) { if (demo) { toast('Comece cadastrando sua primeira conta para personalizar o espaço.', { action: { label: 'Começar', onClick: start } }); return; } resetOperation(); const values: Record<string, string> = { name: '', title: '', amount: '', kind: 'checking', opening: '0', color: colors[0], limit: '', closing: '5', due: '12', type: 'expense', category: expenseCategories[0] ?? 'Outros', subcategory: '', tags: '', accountId: real.accounts.find((account) => account.kind !== 'credit')?.id ?? real.accounts[0]?.id ?? '', toId: '', date: today(), status: 'paid', installments: '1', invoiceMonth: month, month, startDate: today(), nextDate: today(), frequency: 'monthly', endDate: '', active: 'true', parentId: '', ...extra }; if (record) Object.entries(record).forEach(([key, value]) => { if (value !== undefined && value !== null) values[key] = Array.isArray(value) ? value.join(',') : String(value); }); for (const key of ['amount', 'opening', 'limit', 'target', 'saved']) if (record && key in record) values[key] = ((record as unknown as Record<string, number>)[key] / 100).toFixed(2).replace('.', ','); if (record && 'nextDate' in record) values.startDate = String((record as Recurrence).startDate); setEditor({ kind, id: record?.id, values }); }
  function start() { setOnboarding({ accountName: 'Conta principal', accountKind: 'checking', opening: '', income: '', goalName: '', goalTarget: '', goalDate: addMonths(today(), 6) }); setOnboardingStep(1); setOnboardingError(''); setOnboardingOpen(true); }
  function updateOnboarding(key: keyof OnboardingData, value: string) { setOnboarding((current) => ({ ...current, [key]: value })); setOnboardingError(''); }
  async function finishOnboarding(event: FormEvent) { event.preventDefault(); if (saving) return; setOnboardingError(''); setSaving(true); try { if (!onboarding.accountName.trim()) throw new Error('Informe o nome da sua primeira conta.'); const accountResult = await mutate('accounts', 'POST', { name: onboarding.accountName, kind: onboarding.accountKind, opening: money(onboarding.opening || '0'), color: colors[0], limit: 0, closing: 5, due: 12 }, crypto.randomUUID()); if (!accountResult.id) throw new Error('Não conseguimos criar sua primeira conta.'); if (onboarding.income.trim()) await mutate('transactions', 'POST', { title: 'Renda mensal', amount: money(onboarding.income), type: 'income', category: 'Salário', accountId: accountResult.id, date: today(), status: 'paid', installments: 1 }, crypto.randomUUID()); if (onboarding.goalName.trim() || onboarding.goalTarget.trim()) { if (!onboarding.goalName.trim() || !onboarding.goalTarget.trim()) throw new Error('Preencha o nome e o valor da meta, ou deixe os dois campos vazios.'); await mutate('goals', 'POST', { name: onboarding.goalName, target: money(onboarding.goalTarget), saved: 0, date: onboarding.goalDate, color: colors[1] }, crypto.randomUUID()); } setOnboardingOpen(false); setDemo(false); toast.success('Seu espaço está pronto. Vamos dar o próximo passo!'); await refresh(); } catch (error) { setOnboardingError(error instanceof Error ? error.message : 'Não foi possível concluir o cadastro inicial.'); } finally { setSaving(false); } }
  function field(key: string, value: string) { setEditor((current) => current ? { ...current, values: { ...current.values, [key]: value } } : current); setFormError(''); }
  function parseQuick(event: FormEvent) { event.preventDefault(); const match = quick.trim().match(/^(.*?)\s+(\d+(?:[.,]\d{1,2})?)$/); if (!match) { toast('Digite descrição e valor, como “Café 12,50”.'); return; } const title = match[1]; const category = /café|cafe|mercado|almoço|almoco|jantar|lanche/i.test(title) ? 'Alimentação' : /uber|ônibus|onibus|gasolina/i.test(title) ? 'Transporte' : /farmácia|farmacia|academia/i.test(title) ? 'Saúde' : 'Outros'; openEditor('transactions', undefined, { title, amount: match[2], category }); }
  async function save(event: FormEvent) { event.preventDefault(); if (!editor || saving) return; setFormError(''); setSaving(true); try { const values = editor.values; let data: unknown; if (editor.kind === 'accounts') data = { name: values.name, kind: values.kind, opening: money(values.opening || '0'), color: values.color, limit: money(values.limit || '0'), closing: Number(values.closing), due: Number(values.due) }; else if (editor.kind === 'transactions') data = { title: values.title, amount: money(values.amount), type: values.type, category: values.type === 'transfer' ? 'Transferência' : values.category, ...(values.subcategory ? { subcategory: values.subcategory } : {}), ...(splitIds(values.tags).length ? { tags: splitIds(values.tags) } : {}), accountId: values.accountId, ...(values.type === 'transfer' ? { toId: values.toId, invoiceMonth: values.invoiceMonth } : {}), date: values.date, status: values.type === 'transfer' ? 'paid' : values.status, installments: Number(values.installments) }; else if (editor.kind === 'budgets') data = { category: values.category, amount: money(values.amount), month: values.month }; else if (editor.kind === 'goals') data = { name: values.name, target: money(values.target), saved: money(values.saved), date: values.date, color: values.color }; else if (editor.kind === 'recurrences') data = { title: values.title, amount: money(values.amount), type: values.type, category: values.category, ...(values.subcategory ? { subcategory: values.subcategory } : {}), ...(splitIds(values.tags).length ? { tags: splitIds(values.tags) } : {}), accountId: values.accountId, startDate: values.startDate, nextDate: values.nextDate, frequency: values.frequency, ...(values.endDate ? { endDate: values.endDate } : {}), active: values.active === 'true' }; else if (editor.kind === 'categories') data = { name: values.name, type: values.type, ...(values.parentId ? { parentId: values.parentId } : {}), color: values.color }; else data = { name: values.name, color: values.color }; await mutate(editor.kind, editor.id ? 'PUT' : 'POST', data, crypto.randomUUID(), editor.id); setEditor(null); setQuick(''); toast.success(editor.kind === 'recurrences' ? 'Recorrência salva.' : 'Salvo. Mais um passo dado!'); await refresh(); } catch (error) { setFormError(error instanceof Error ? error.message : 'Não foi possível salvar.'); } finally { setSaving(false); } }
  async function remove() { if (!deletion || saving) return; setSaving(true); try { await mutate(deletion.kind, 'DELETE', null, crypto.randomUUID(), deletion.id); setDeletion(null); toast.success('Registro excluído.'); await refresh(); } catch (error) { toast.error(error instanceof Error ? error.message : 'Não foi possível excluir.'); } finally { setSaving(false); } }
  function askDelete(kind: FormKind, id: string, name: string) { if (demo) { toast('Os dados desta prévia são fictícios.'); return; } setDeletion({ kind, id, name }); }
  function exportCsv() { const rows = [['Data', 'Descrição', 'Tipo', 'Categoria', 'Subcategoria', 'Valor', 'Conta', 'Status'], ...txSorted.map((transaction) => [transaction.date, transaction.title, transaction.type === 'expense' ? 'Despesa' : transaction.type === 'income' ? 'Receita' : 'Transferência', transaction.category, transaction.subcategory ?? '', (transaction.amount / 100).toFixed(2).replace('.', ','), state.accounts.find((account) => account.id === transaction.accountId)?.name ?? '', transaction.status === 'paid' ? 'Concluído' : 'Pendente'])]; const escape = (value: string) => `"${(/^[=+\-@\t\r]/.test(value) ? `'${value}` : value).replace(/"/g, '""')}"`; const blob = new Blob(['\ufeff' + rows.map((row) => row.map(escape).join(';')).join('\r\n')], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `clareza-${month}${demo ? '-exemplo' : ''}.csv`; anchor.click(); URL.revokeObjectURL(url); toast.success('Lançamentos exportados.'); }

  const txTable = (compact = false) => <Table><TableHeader><TableRow><TableHead>Descrição</TableHead><TableHead className="hide-small">Data</TableHead>{!compact && <TableHead className="hide-small">Conta</TableHead>}<TableHead className="text-right">Valor</TableHead>{!compact && <TableHead className="text-right">Ações</TableHead>}</TableRow></TableHeader><TableBody>{(compact ? [...stats.tx].sort((a, b) => b.date.localeCompare(a.date)).slice(0, 5) : txSorted).map((transaction) => <TableRow key={transaction.id}><TableCell><div className="transaction-name"><CategoryIcon category={transaction.category} color={categoryColor(transaction.category)} /><div><strong>{transaction.title}{(transaction.installments ?? 1) > 1 && ` · ${transaction.installment}/${transaction.installments}`}</strong><span>{transaction.category}{transaction.subcategory ? ` · ${transaction.subcategory}` : ''}{isPending(transaction) && <em> · {state.accounts.find((account) => account.id === transaction.accountId)?.kind === 'credit' ? 'Na fatura' : 'Pendente'}</em>}</span></div></div></TableCell><TableCell className="hide-small metadata">{shortDate(transaction.date)}</TableCell>{!compact && <TableCell className="hide-small metadata">{state.accounts.find((account) => account.id === transaction.accountId)?.name}</TableCell>}<TableCell className={`amount text-right ${transaction.type === 'income' ? 'income' : ''}`}>{transaction.type === 'income' ? '+' : transaction.type === 'expense' ? '−' : ''} {displayMoney(transaction.amount)}</TableCell>{!compact && <TableCell><div className="row-actions">{(transaction.installments ?? 1) === 1 && <button className="icon-button" aria-label={`Editar ${transaction.title}`} onClick={() => openEditor('transactions', transaction)}><Pencil size={16} /></button>}<button className="icon-button" aria-label={`Excluir ${transaction.title}`} onClick={() => askDelete('transactions', transaction.id, transaction.title)}><Trash2 size={16} /></button></div></TableCell>}</TableRow>)}</TableBody></Table>;
  const goalCard = (goal: Goal) => { const percentage = Math.min(100, Math.round(goal.saved / goal.target * 100)); const remaining = Math.max(0, goal.target - goal.saved); const monthly = remaining ? Math.ceil(remaining / monthsUntil(goal.date)) : 0; return <article className="goal-item" key={goal.id}><div className="section-head"><span className="category-icon" style={{ background: `${goal.color}18`, color: goal.color }}><Target size={20} /></span><span className="goal-percent">{percentage}%</span></div><h3>{goal.name}</h3><p><strong>{displayMoney(goal.saved)}</strong> <span>de {displayMoney(goal.target)}</span></p><Progress value={percentage} style={{ '--progress-color': goal.color } as CSSProperties} /><div className="goal-smart"><Sparkles size={14} />{remaining ? `Sugestão: ${displayMoney(monthly)} por mês` : 'Meta concluída. Que conquista!'}</div><div className="goal-bottom"><span>{shortDate(goal.date)} de {goal.date.slice(0, 4)}</span><button className="text-button" onClick={() => openEditor('goals', goal)}>Atualizar <ArrowUpRight size={15} /></button>{view === 'goals' && <button className="icon-button" aria-label={`Excluir meta ${goal.name}`} onClick={() => askDelete('goals', goal.id, goal.name)}><Trash2 size={15} /></button>}</div></article>; };
  const agendaRow = (item: AgendaItem) => <div className="agenda-row" key={item.id}><div className={`agenda-date ${item.date < currentDate ? 'overdue' : ''}`}><strong>{item.date.slice(-2)}</strong><span>{new Date(`${item.date}T12:00:00`).toLocaleDateString('pt-BR', { month: 'short' }).replace('.', '')}</span></div><div className="agenda-main"><strong>{item.title}</strong><span>{item.date < currentDate ? 'Vencido' : shortDate(item.date)} · {item.recurring ? 'Recorrente' : item.category}</span></div><strong className={item.type === 'income' ? 'income' : ''}>{item.type === 'income' ? '+' : '−'} {displayMoney(item.amount)}</strong></div>;
  const alertCard = (alert: AlertItem) => <div className={`alert-item ${alert.tone}`} key={alert.id}><span className="alert-icon">{alert.tone === 'warning' ? <CircleAlert size={17} /> : <CheckCircle2 size={17} />}</span><div><strong>{alert.title}</strong><p>{alert.detail}</p></div></div>;
  const actionKind: FormKind = view === 'accounts' ? 'accounts' : view === 'budgets' ? 'budgets' : view === 'goals' ? 'goals' : view === 'categories' ? 'categories' : view === 'agenda' ? 'recurrences' : 'transactions';
  const actionLabel = actionKind === 'accounts' ? 'Nova conta' : actionKind === 'budgets' ? 'Novo orçamento' : actionKind === 'goals' ? 'Nova meta' : actionKind === 'categories' ? 'Nova categoria' : actionKind === 'recurrences' ? 'Nova recorrência' : 'Novo lançamento';
  const pageDescription = view === 'overview' ? 'Um pequeno registro hoje faz diferença amanhã.' : view === 'transactions' ? 'Cada movimento conta. Registre, revise e siga em frente.' : view === 'agenda' ? 'Veja o que pede atenção agora e o que vem pela frente.' : view === 'accounts' ? 'Todas as suas contas e cartões, lado a lado.' : view === 'budgets' ? 'Dê um destino ao seu dinheiro, sem rigidez.' : view === 'goals' ? 'Transforme planos em pequenas conquistas.' : 'Deixe sua linguagem financeira com a sua cara.';

  return <SidebarProvider style={{ '--sidebar-width': '235px' } as CSSProperties}><Navigation view={view} onNav={setView} focus={focus} setFocus={(value) => preference('focus', value)} user={user} onLogout={() => void signOut()} /><div className={`workspace ${focus ? 'focus-mode' : ''} ${hidden ? 'privacy-mode' : ''}`}><header className="topbar"><div className="breadcrumb"><SidebarTrigger className="mobile-menu" /><span>Meu espaço</span><ChevronRight size={14} /><strong>{nav.find((item) => item[0] === view)?.[1]}</strong></div><div className="top-actions"><span className="private-label"><ShieldCheck size={15} /> Espaço privado</span><button className="icon-button" onClick={() => preference('hidden', !hidden)} aria-label={hidden ? 'Mostrar valores' : 'Ocultar valores'}>{hidden ? <EyeOff size={19} /> : <Eye size={19} />}</button><span className="top-avatar">{user.name.trim().slice(0, 2).toUpperCase() || 'EU'}</span></div></header><main className="main-content"><div className="page-title"><div><span className="eyebrow">{view === 'overview' ? 'MENOS RUÍDO. MAIS CLAREZA.' : 'SEU DINHEIRO, ORGANIZADO'}</span><h1>{view === 'overview' ? 'Seu dinheiro, no seu ritmo.' : nav.find((item) => item[0] === view)?.[1]}</h1><p>{pageDescription}</p></div><div className="title-actions"><div className="month-picker"><button aria-label="Mês anterior" onClick={() => setMonth(addMonths(`${month}-01`, -1).slice(0, 7))}><ChevronLeft size={17} /></button><span>{monthLabel(month)}</span><button aria-label="Próximo mês" onClick={() => setMonth(addMonths(`${month}-01`, 1).slice(0, 7))}><ChevronRight size={17} /></button></div><button className="primary-button" onClick={() => demo ? start() : openEditor(actionKind)}><Plus size={19} />{actionLabel}</button></div></div>
  {demo && <div className="demo-banner"><span><Info size={16} /><strong>Você está explorando um exemplo.</strong> Estes valores são fictícios.</span><button onClick={start}>Começar minhas finanças <ArrowRight size={16} /></button></div>}
  {loadError ? <div className="error-card" role="alert"><h2>Não conseguimos carregar suas finanças.</h2><p>{loadError}</p><button className="primary-button" onClick={() => void refresh()}>Tentar novamente</button><button type="button" onClick={() => void signOut()} className="text-button">Voltar para entrar</button></div> : loading ? <div className="loading-grid" aria-label="Carregando finanças"><Skeleton className="h-56 rounded-2xl" /><Skeleton className="h-56 rounded-2xl" /><Skeleton className="h-80 rounded-2xl" /></div> : <>
    {view === 'overview' && <><section className="summary-grid"><article className="balance-card"><div className="card-eyebrow"><Wallet size={17} /><span>Disponível após compromissos</span><button className="icon-button" onClick={() => preference('hidden', !hidden)} aria-label="Alternar visibilidade do saldo">{hidden ? <EyeOff size={17} /> : <Eye size={17} />}</button></div><div className={`big-balance ${available < 0 ? 'negative' : ''}`}>{displayMoney(available)}</div><div className="balance-note"><span className="balance-status"><span />{available >= 0 ? 'Um panorama do que você tem hoje' : 'Vamos reorganizar os próximos passos'}</span></div><div className="balance-bottom"><span>Saldo em contas <strong>{displayMoney(cash)}</strong></span><span title="Despesas pendentes e toda a dívida dos cartões.">Compromissos <strong>{displayMoney(cardDebt + cashPending)}</strong></span></div></article><article className="metric-card"><span className="metric-icon green"><ArrowDownLeft size={22} /></span><span className="metric-label">Receitas do mês</span><strong>{displayMoney(stats.income)}</strong><p>Recebidas e previstas</p><div className="metric-rule green-rule" /><span className="metric-foot">Tudo que entra</span></article><article className="metric-card"><span className="metric-icon orange"><ArrowUpRight size={22} /></span><span className="metric-label">Despesas do mês</span><strong>{displayMoney(stats.expense)}</strong><p>Pagas e previstas</p><div className="metric-rule orange-rule" /><span className="metric-foot">Inclui parcelas com vencimento</span></article></section><section className="quick-entry"><span className="quick-icon"><Plus size={20} /></span><div><strong>Registro rápido</strong><span>Digite uma descrição e um valor</span></div><form onSubmit={parseQuick}><input value={quick} onChange={(event) => setQuick(event.target.value)} placeholder="Ex.: café 12,50" aria-label="Registro rápido" /><button type="submit">Adicionar <ArrowRight size={15} /></button></form></section>{alerts.length > 0 && <section className="panel alert-panel"><div className="section-head"><div><h2><Bell size={17} /> Alertas para você</h2><p>Pequenos lembretes para manter o controle.</p></div><span className="mini-badge">{alerts.length}</span></div><div className="alert-grid">{alerts.slice(0, 3).map(alertCard)}</div></section>}<div className="dashboard-grid"><div className="main-column"><section className="panel spending-panel"><div className="section-head"><div><h2>Para onde foi seu dinheiro</h2><p>Despesas acumuladas em {monthLabel(month)}</p></div><span className="mini-badge">{categoryData.length} categorias</span></div>{categoryData.length ? <div className="spending-content"><div className="donut-wrapper"><ResponsiveContainer width="100%" height={220}><PieChart><Pie data={categoryData} dataKey="value" nameKey="name" innerRadius={68} outerRadius={95} paddingAngle={3}>{categoryData.map((category) => <Cell key={category.name} fill={categoryColor(category.name)} />)}</Pie><Tooltip formatter={(value) => brl(Number(value))} /></PieChart></ResponsiveContainer><div className="donut-center"><span>Total</span><strong>{displayMoney(stats.expense)}</strong></div></div><div className="category-legend">{categoryData.slice(0, 5).map((category) => <div key={category.name}><span><i style={{ background: categoryColor(category.name) }} />{category.name}</span><strong>{displayMoney(category.value)}</strong><small>{Math.round(category.value / Math.max(1, stats.expense) * 100)}%</small></div>)}</div></div> : <Empty title="Ainda não há gastos neste mês." text="Registre o próximo movimento para começar a enxergar seus padrões." />}</section><section className="panel chart-panel"><div className="section-head"><div><h2>Fluxo do mês</h2><p>Receitas e despesas acumuladas</p></div><div className="chart-legend"><span><i className="green-dot" />Receitas</span><span><i className="orange-dot" />Despesas</span></div></div><ResponsiveContainer width="100%" height={190}><AreaChart data={chartData}><defs><linearGradient id="incomeFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#65b589" stopOpacity={.25} /><stop offset="100%" stopColor="#65b589" stopOpacity={0} /></linearGradient><linearGradient id="expenseFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#dba66e" stopOpacity={.2} /><stop offset="100%" stopColor="#dba66e" stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="#edf1ed" /><XAxis dataKey="day" tickLine={false} axisLine={false} tick={{ fontSize: 10, fill: '#9aa69b' }} interval={4} /><YAxis hide /><Tooltip formatter={(value) => brl(Math.round(Number(value) * 100))} /><Area type="monotone" dataKey="income" stroke="#57ab7d" fill="url(#incomeFill)" strokeWidth={2} name="Receitas" /><Area type="monotone" dataKey="expense" stroke="#d8a165" fill="url(#expenseFill)" strokeWidth={2} name="Despesas" /></AreaChart></ResponsiveContainer></section><section className="panel recent-panel"><div className="section-head"><div><h2>Últimos lançamentos</h2><p>Um olhar rápido no seu mês</p></div><button className="text-button" onClick={() => { setSearch(''); setFilter('all'); setView('transactions'); }}>Ver todos <ArrowRight size={15} /></button></div>{stats.tx.length ? txTable(true) : <Empty title="Ainda sem lançamentos." text="Comece pelo próximo café, almoço ou pagamento." />}</section></div><aside className="right-column"><section className="panel agenda"><div className="section-head"><div><h2>Próximos compromissos</h2><p>Até os próximos 30 dias</p></div><CalendarDays size={18} /></div>{agendaItems.length ? agendaItems.slice(0, 4).map(agendaRow) : <div className="agenda-empty"><CheckCircle2 size={24} /><p>Nenhuma conta pendente por aqui.</p></div>}<button className="agenda-link" onClick={() => setView('agenda')}>Abrir agenda completa <ArrowRight size={16} /></button></section><section className="panel insights-panel"><div className="section-head"><div><h2><Sparkles size={17} /> Insights automáticos</h2><p>Leituras simples, sem julgamento.</p></div><Lightbulb size={18} /></div>{insights.map((insight) => <div className="insight-item" key={insight.id}><span><insight.icon size={17} /></span><div><strong>{insight.title}</strong><p>{insight.detail}</p></div></div>)}</section><section className="panel secondary budget-overview"><div className="section-head"><h2>De olho no orçamento</h2><button className="icon-button" aria-label="Ver orçamentos" onClick={() => setView('budgets')}><ArrowUpRight size={19} /></button></div>{monthlyBudgets.length ? monthlyBudgets.slice(0, 3).map((budget) => { const spent = categoryData.find((category) => category.name === budget.category)?.value ?? 0; const percentage = Math.round(spent / budget.amount * 100); return <div className="budget-mini" key={budget.id}><div><span>{budget.category}</span><strong>{percentage}%</strong></div><Progress value={Math.min(100, percentage)} style={{ '--progress-color': percentage > 100 ? '#c65b48' : categoryColor(budget.category) } as CSSProperties} /><small>{displayMoney(spent)} de {displayMoney(budget.amount)}</small></div>; }) : <p className="soft-text">Defina um valor por categoria para acompanhar seus limites.</p>}</section></aside></div><section className="panel goals-overview secondary"><div className="section-head"><div><h2>Seus próximos motivos para guardar</h2><p>Agora com uma sugestão mensal para cada meta.</p></div><button className="text-button" onClick={() => setView('goals')}>Minhas metas <ArrowRight size={15} /></button></div>{state.goals.length ? <div className="goals-grid">{state.goals.slice(0, 2).map(goalCard)}</div> : <Empty title="O que você quer conquistar?" text="Uma reserva, uma viagem ou um plano só seu." action={<button className="text-button" onClick={() => openEditor('goals')}>Criar uma meta <Plus size={16} /></button>} />}</section></>}
    {view === 'transactions' && <section className="panel"><div className="transaction-controls"><Tabs value={filter} onValueChange={setFilter}><TabsList><TabsTrigger value="all">Todos</TabsTrigger><TabsTrigger value="expense">Despesas</TabsTrigger><TabsTrigger value="income">Receitas</TabsTrigger><TabsTrigger value="pending">Pendentes</TabsTrigger></TabsList></Tabs><div className="search-actions"><label className="search-field"><Search size={17} /><input placeholder="Buscar lançamento" value={search} onChange={(event) => setSearch(event.target.value)} aria-label="Buscar lançamento" /></label><button className="secondary-button" onClick={exportCsv}><Download size={17} /> CSV</button></div></div>{txSorted.length ? txTable() : <Empty title="Nenhum lançamento por aqui." text="Tente outro mês ou filtro, ou registre um novo movimento." action={<button className="primary-button" onClick={() => openEditor('transactions')}><Plus size={17} /> Novo lançamento</button>} />}</section>}
    {view === 'agenda' && <><section className="panel agenda-page"><div className="section-head"><div><h2>O que pede atenção</h2><p>Contas pendentes e recorrências dos próximos 30 dias.</p></div><Bell size={19} /></div>{agendaItems.length ? agendaItems.map(agendaRow) : <Empty title="Agenda tranquila." text="Quando você registrar compromissos, eles aparecerão aqui." />}</section><section className="panel recurrence-panel"><div className="section-head"><div><h2>Lançamentos recorrentes</h2><p>O Clareza cria o lançamento quando chega a data, sem serviço externo.</p></div><button className="primary-button" onClick={() => openEditor('recurrences')}><Plus size={16} /> Nova recorrência</button></div>{state.recurrences.length ? <div className="recurrence-list">{state.recurrences.map((recurrence) => <div className="recurrence-row" key={recurrence.id}><span className="recurrence-icon"><Repeat size={17} /></span><div><strong>{recurrence.title}</strong><span>{frequencyLabels[recurrence.frequency]} · {recurrence.category} · próximo em {shortDate(recurrence.nextDate)}</span></div><strong className={recurrence.active ? '' : 'muted-status'}>{recurrence.active ? displayMoney(recurrence.amount) : 'Pausada'}</strong><div className="row-actions"><button className="icon-button" aria-label={`Editar recorrência ${recurrence.title}`} onClick={() => openEditor('recurrences', recurrence)}><Pencil size={16} /></button><button className="icon-button" aria-label={`Excluir recorrência ${recurrence.title}`} onClick={() => askDelete('recurrences', recurrence.id, recurrence.title)}><Trash2 size={16} /></button></div></div>)}</div> : <Empty title="Nenhuma recorrência ainda." text="Cadastre salário, aluguel ou assinaturas para não precisar repetir o mesmo trabalho." action={<button className="primary-button" onClick={() => openEditor('recurrences')}><Plus size={16} /> Cadastrar recorrência</button>} />}</section></>}
    {view === 'accounts' && <><div className="section-head accounts-head"><h2>Minhas contas <span className="mini-badge">{state.accounts.filter((account) => account.kind !== 'credit').length}</span></h2><button className="text-button" onClick={() => openEditor('accounts')}>Adicionar conta <Plus size={16} /></button></div><div className="account-grid">{state.accounts.filter((account) => account.kind !== 'credit').map((account) => <article className="panel account-card" key={account.id}><div className="section-head"><span className="bank-symbol" style={{ background: account.color }}>{account.name.slice(0, 2).toUpperCase()}</span><div className="row-actions"><button className="icon-button" aria-label={`Editar ${account.name}`} onClick={() => openEditor('accounts', account)}><Pencil size={16} /></button><button className="icon-button" aria-label={`Excluir ${account.name}`} onClick={() => askDelete('accounts', account.id, account.name)}><Trash2 size={16} /></button></div></div><h3>{account.name}</h3><span className="soft-text">{account.kind === 'cash' ? 'Dinheiro em mãos' : 'Conta bancária'}</span><div className="account-balance"><span>Saldo atual</span><strong>{displayMoney(balancesByAccount[account.id] ?? 0)}</strong></div></article>)}</div><div className="section-head accounts-head"><h2>Cartões de crédito</h2><button className="text-button" onClick={() => openEditor('accounts', undefined, { kind: 'credit' })}>Adicionar cartão <Plus size={16} /></button></div><div className="account-grid">{state.accounts.filter((account) => account.kind === 'credit').map((account) => { const invoice = invoiceBalance(state, account.id, month); return <article className="panel credit-container" key={account.id}><div className="credit-face" style={{ background: account.color }}><div><strong>{account.name}</strong><CreditCard size={26} /></div><span>Fatura de {monthLabel(month)}</span><strong>{displayMoney(invoice)}</strong><div><small>Fecha dia {account.closing}</small><small>Vence dia {account.due}</small></div></div><div className="credit-info"><span>Dívida total, incluindo parcelas futuras <strong>{displayMoney(Math.max(0, -(balancesByAccount[account.id] ?? 0)))}</strong></span><span>Limite cadastrado <strong>{displayMoney(account.limit)}</strong></span><Progress value={account.limit ? Math.min(100, Math.max(0, -(balancesByAccount[account.id] ?? 0)) / account.limit * 100) : 0} /><div className="row-actions"><button className="text-button" onClick={() => openEditor('transactions', undefined, { type: 'transfer', toId: account.id, title: `Pagamento · ${account.name}`, invoiceMonth: month, amount: (invoice / 100).toFixed(2), date: today() })}>Registrar pagamento <ArrowUpRight size={16} /></button><button className="icon-button" aria-label={`Editar ${account.name}`} onClick={() => openEditor('accounts', account)}><Pencil size={16} /></button><button className="icon-button" aria-label={`Excluir ${account.name}`} onClick={() => askDelete('accounts', account.id, account.name)}><Trash2 size={16} /></button></div></div></article>; })}</div>{!state.accounts.length && <section className="panel"><Empty title="Todas as suas contas, um só lugar." text="Cadastre o saldo atual de uma conta para começar." action={<button className="primary-button" onClick={start}>Adicionar conta</button>} /></section>}<div className="info-note"><Info size={18} /><p>Os saldos são calculados pelos seus registros. O pagamento do cartão é uma transferência e não soma uma nova despesa.</p></div></>}
    {view === 'budgets' && <><div className="budget-header panel"><div><span>Planejado para o mês</span><strong>{displayMoney(monthlyBudgets.reduce((sum, budget) => sum + budget.amount, 0))}</strong></div><div><span>Gastos nas categorias planejadas</span><strong>{displayMoney(monthlyBudgets.reduce((sum, budget) => sum + (categoryData.find((category) => category.name === budget.category)?.value ?? 0), 0))}</strong></div><p>Seu orçamento é um guia.<br />Você pode ajustá-lo quando precisar.</p></div><div className="budget-grid">{monthlyBudgets.map((budget) => { const spent = categoryData.find((category) => category.name === budget.category)?.value ?? 0; const percentage = Math.round(spent / budget.amount * 100); return <article className="panel budget-card" key={budget.id}><div className="section-head"><CategoryIcon category={budget.category} color={categoryColor(budget.category)} /><div className="row-actions"><button className="icon-button" aria-label={`Editar orçamento ${budget.category}`} onClick={() => openEditor('budgets', budget)}><Pencil size={16} /></button><button className="icon-button" aria-label={`Excluir orçamento ${budget.category}`} onClick={() => askDelete('budgets', budget.id, budget.category)}><Trash2 size={16} /></button></div></div><h3>{budget.category}</h3><div className="budget-values"><strong>{displayMoney(spent)}</strong><span>de {displayMoney(budget.amount)}</span></div><Progress value={Math.min(100, percentage)} style={{ '--progress-color': percentage > 100 ? '#c65b48' : categoryColor(budget.category) } as CSSProperties} /><p className={percentage > 100 ? 'over-budget' : 'under-budget'}>{percentage > 100 ? `${displayMoney(spent - budget.amount)} acima do planejado` : `${displayMoney(budget.amount - spent)} para usar no mês`}</p></article>; })}</div>{!monthlyBudgets.length && <section className="panel"><Empty title="Comece com uma categoria." text="Escolha um limite confortável. Você pode ajustar depois." action={<button className="primary-button" onClick={() => openEditor('budgets')}>Criar orçamento</button>} /></section>}</>}
    {view === 'goals' && <><div className="goals-grid standalone-goals">{state.goals.map(goalCard)}</div>{!state.goals.length && <section className="panel"><Empty title="Qual é seu próximo plano?" text="Dê um nome à sua meta e acompanhe o que já guardou." action={<button className="primary-button" onClick={() => openEditor('goals')}>Criar minha primeira meta</button>} /></section>}<div className="info-note"><Info size={18} /><p>Agora o Clareza sugere um valor mensal com base no que falta e no prazo informado. Atualizar a meta não movimenta suas contas.</p></div></>}
    {view === 'categories' && <><section className="panel taxonomy-header"><div><h2>Deixe seu controle com a sua linguagem</h2><p>Crie categorias, subcategorias e tags para encontrar padrões que fazem sentido para você.</p></div><div className="row-actions"><button className="secondary-button" onClick={() => openEditor('tags')}><TagIcon size={16} /> Nova tag</button><button className="primary-button" onClick={() => openEditor('categories')}><Plus size={16} /> Nova categoria</button></div></section><div className="taxonomy-grid"><section className="panel"><div className="section-head"><div><h2>Categorias padrão</h2><p>Prontas para começar, sem configuração.</p></div><ListChecks size={18} /></div><div className="taxonomy-list">{categories.map((category) => <div className="taxonomy-row" key={category}><CategoryIcon category={category} color={categoryColor(category)} /><span>{category}</span><small>{categoryType(category) === 'income' ? 'Entrada' : 'Saída'}</small></div>)}</div></section><section className="panel"><div className="section-head"><div><h2>Suas categorias</h2><p>Subcategorias ficam agrupadas pela categoria pai.</p></div><Tags size={18} /></div>{state.categories.length ? <div className="taxonomy-list">{state.categories.map((category) => <div className="taxonomy-row" key={category.id}><CategoryIcon category={category.name} color={category.color} /><span>{category.parentId ? `↳ ${category.name}` : category.name}</span><small>{category.type === 'income' ? 'Entrada' : 'Saída'}<button className="icon-button" aria-label={`Excluir ${category.name}`} onClick={() => askDelete('categories', category.id, category.name)}><Trash2 size={15} /></button></small></div>)}</div> : <Empty title="Personalize quando quiser." text="Crie uma categoria como “Pets”, “Cursos” ou “Renda extra” para organizar melhor seus registros." action={<button className="text-button" onClick={() => openEditor('categories')}>Criar categoria <Plus size={15} /></button>} />}</section><section className="panel"><div className="section-head"><div><h2>Tags</h2><p>Uma camada extra para cruzar seus lançamentos.</p></div><TagIcon size={18} /></div>{state.tags.length ? <div className="tag-list">{state.tags.map((tag) => <span className="tag-chip" style={{ '--tag-color': tag.color } as CSSProperties} key={tag.id}>{tag.name}<button aria-label={`Excluir tag ${tag.name}`} onClick={() => askDelete('tags', tag.id, tag.name)}>×</button></span>)}</div> : <Empty title="Nenhuma tag criada." text="Use tags para separar projetos, pessoas ou tipos de compra." action={<button className="text-button" onClick={() => openEditor('tags')}>Criar tag <Plus size={15} /></button>} />}</section></div></>}
  </>}</main><footer className="page-footer"><span><Leaf size={14} /> Feito para a vida real.</span><span>Um passo de cada vez.</span></footer></div>

  <Dialog open={onboardingOpen} onOpenChange={(open) => { if (!saving) setOnboardingOpen(open); }}><DialogContent className="onboarding-dialog"><DialogHeader><span className="modal-kicker">SEU PRIMEIRO PASSO</span><DialogTitle>Vamos deixar tudo mais claro</DialogTitle><DialogDescription>Em três passos rápidos, você cria um ponto de partida para suas finanças.</DialogDescription></DialogHeader><div className="onboarding-progress"><div><span>Passo {onboardingStep} de 3</span><strong>{onboardingStep === 1 ? 'Seu ponto de partida' : onboardingStep === 2 ? 'Sua renda' : 'Um plano para guardar'}</strong></div><Progress value={onboardingStep / 3 * 100} /></div><form onSubmit={onboardingStep === 3 ? finishOnboarding : (event) => { event.preventDefault(); setOnboardingStep((step) => step + 1); }} className="onboarding-form">{onboardingStep === 1 && <><label className="field"><span>Como você chama sua primeira conta?</span><input autoFocus required value={onboarding.accountName} onChange={(event) => updateOnboarding('accountName', event.target.value)} placeholder="Ex.: conta principal" /></label><Picker label="Tipo de conta" value={onboarding.accountKind} onChange={(value) => updateOnboarding('accountKind', value)} options={[{ value: 'checking', label: 'Conta bancária' }, { value: 'cash', label: 'Dinheiro / carteira' }]} /><label className="field"><span>Quanto você tem disponível hoje? <small>(opcional)</small></span><input inputMode="decimal" value={onboarding.opening} onChange={(event) => updateOnboarding('opening', event.target.value)} placeholder="0,00" /></label></>}{onboardingStep === 2 && <><div className="onboarding-tip"><TrendingUp size={21} /><div><strong>Não precisa ser perfeito.</strong><p>Uma estimativa de renda mensal já ajuda a projetar seus próximos compromissos.</p></div></div><label className="field"><span>Qual é sua renda mensal? <small>(opcional)</small></span><div className="amount-input"><div><span>R$</span><input autoFocus inputMode="decimal" value={onboarding.income} onChange={(event) => updateOnboarding('income', event.target.value)} placeholder="0,00" /></div></div></label></>}{onboardingStep === 3 && <><div className="onboarding-tip"><Target size={21} /><div><strong>Ter um motivo ajuda a continuar.</strong><p>Se quiser, crie uma meta agora. Você poderá editar depois.</p></div></div><label className="field"><span>O que você quer conquistar? <small>(opcional)</small></span><input autoFocus value={onboarding.goalName} onChange={(event) => updateOnboarding('goalName', event.target.value)} placeholder="Ex.: reserva de emergência" /></label><div className="form-grid"><label className="field"><span>Valor da meta <small>(opcional)</small></span><input inputMode="decimal" value={onboarding.goalTarget} onChange={(event) => updateOnboarding('goalTarget', event.target.value)} placeholder="10.000,00" /></label><label className="field"><span>Prazo</span><input type="date" value={onboarding.goalDate} onChange={(event) => updateOnboarding('goalDate', event.target.value)} /></label></div></>}{onboardingError && <p className="form-error" role="alert">{onboardingError}</p>}<div className="form-footer"><button type="button" className="secondary-button" disabled={saving} onClick={() => onboardingStep === 1 ? setOnboardingOpen(false) : setOnboardingStep((step) => step - 1)}>{onboardingStep === 1 ? 'Agora não' : 'Voltar'}</button><button className="primary-button" disabled={saving} type="submit">{saving ? <LoaderCircle className="spin" size={17} /> : onboardingStep === 3 ? <Check size={17} /> : <ArrowRight size={17} />} {saving ? 'Preparando…' : onboardingStep === 3 ? 'Entrar no meu espaço' : 'Continuar'}</button></div><p className="form-reassurance"><ShieldCheck size={14} /> Seus registros ficam no seu espaço privado.</p></form></DialogContent></Dialog>

  <Dialog open={!!editor} onOpenChange={(open) => { if (!open && !saving) setEditor(null); }}><DialogContent className="editor-dialog"><DialogHeader><span className="modal-kicker">SEU PRÓXIMO PEQUENO PASSO</span><DialogTitle>{editor?.id ? 'Editar ' : editor?.kind === 'transactions' ? 'Novo ' : editor?.kind === 'accounts' ? 'Nova ' : 'Novo '}{editor?.kind === 'transactions' ? 'lançamento' : editor?.kind === 'accounts' ? 'conta ou cartão' : editor?.kind === 'budgets' ? 'orçamento' : editor?.kind === 'goals' ? 'objetivo' : editor?.kind === 'recurrences' ? 'lançamento recorrente' : editor?.kind === 'categories' ? 'categoria' : 'tag'}</DialogTitle><DialogDescription>{editor?.kind === 'transactions' ? 'Confira os detalhes e pronto. Não precisa complicar.' : editor?.kind === 'recurrences' ? 'O Clareza cuidará dos próximos lançamentos para você.' : editor?.kind === 'categories' ? 'Crie uma categoria ou transforme-a em subcategoria.' : editor?.kind === 'tags' ? 'Use uma palavra curta para encontrar padrões depois.' : editor?.kind === 'accounts' ? 'Use o saldo atual como ponto de partida.' : editor?.kind === 'goals' ? 'Um nome, um valor e algo para conquistar.' : 'Escolha uma categoria e um limite para o mês.'}</DialogDescription></DialogHeader>{editor && <form onSubmit={save} className="editor-form">
    {editor.kind === 'transactions' && <><Tabs value={editor.values.type} onValueChange={(value) => { field('type', value); if (value === 'transfer') { field('installments', '1'); field('status', 'paid'); } if (value === 'income') { field('category', 'Salário'); field('installments', '1'); } }}><TabsList className="w-full"><TabsTrigger value="expense">Despesa</TabsTrigger><TabsTrigger value="income">Receita</TabsTrigger><TabsTrigger value="transfer">Transferência</TabsTrigger></TabsList></Tabs><label className="amount-input field"><span>{Number(editor.values.installments) > 1 ? 'Valor total da compra' : 'Quanto?'}</span><div><span>R$</span><input autoFocus required inputMode="decimal" value={editor.values.amount} onChange={(event) => field('amount', event.target.value)} placeholder="0,00" aria-label="Valor" /></div></label><label className="field"><span>Descrição</span><input required maxLength={100} value={editor.values.title} onChange={(event) => field('title', event.target.value)} placeholder="Ex.: almoço, mercado, salário" /></label><div className="form-grid"><Picker label={editor.values.type === 'transfer' ? 'Conta de origem' : 'Conta ou cartão'} value={editor.values.accountId} onChange={(value) => { field('accountId', value); field('installments', '1'); if (state.accounts.find((account) => account.id === value)?.kind === 'credit') field('status', 'pending'); }} options={state.accounts.filter((account) => editor.values.type === 'expense' || account.kind !== 'credit').map((account) => ({ value: account.id, label: account.name }))} />{editor.values.type === 'transfer' ? <Picker label="Conta de destino" value={editor.values.toId} onChange={(value) => field('toId', value)} options={state.accounts.filter((account) => account.id !== editor.values.accountId).map((account) => ({ value: account.id, label: account.name }))} allowEmpty /> : <Picker label="Categoria" value={editor.values.category} onChange={(value) => { field('category', value); field('subcategory', ''); }} options={topLevelCategories(editor.values.type === 'income' ? 'income' : 'expense')} />}<label className="field"><span>{editor.id && state.accounts.find((account) => account.id === editor.values.accountId)?.kind === 'credit' ? 'Vencimento da parcela' : 'Data'}</span><input type="date" required value={editor.values.date} onChange={(event) => field('date', event.target.value)} /></label>{editor.values.type !== 'transfer' && (state.accounts.find((account) => account.id === editor.values.accountId)?.kind === 'credit' ? <label className="field"><span>Parcelas {editor.id ? '(nova compra para parcelar)' : ''}</span><input type="number" min="1" max="48" disabled={!!editor.id} required value={editor.values.installments} onChange={(event) => field('installments', event.target.value)} /></label> : <Picker label="Situação" value={editor.values.status} onChange={(value) => field('status', value)} options={[{ value: 'paid', label: editor.values.type === 'income' ? 'Recebido' : 'Pago' }, { value: 'pending', label: editor.values.type === 'income' ? 'A receber' : 'A pagar' }]} />)}</div>{editor.values.type !== 'transfer' && subcategoriesFor(editor.values.category).length > 0 && <Picker label="Subcategoria" value={editor.values.subcategory} onChange={(value) => field('subcategory', value)} options={subcategoriesFor(editor.values.category)} allowEmpty />}{editor.values.type !== 'transfer' && state.tags.length > 0 && <TagPicker tags={state.tags} value={editor.values.tags} onChange={(value) => field('tags', value)} />}{editor.values.type === 'transfer' && state.accounts.find((account) => account.id === editor.values.toId)?.kind === 'credit' && <label className="field"><span>Fatura que estou pagando</span><input type="month" required value={editor.values.invoiceMonth} onChange={(event) => field('invoiceMonth', event.target.value)} /></label>}{!state.accounts.length && <p className="form-warning">Cadastre uma conta na seção “Contas e cartões” antes de lançar.</p>}{state.accounts.find((account) => account.id === editor.values.accountId)?.kind === 'credit' && <p className="form-hint">Compras a partir do dia de fechamento entram na próxima fatura. O valor total será dividido entre as parcelas.</p>}</>}
    {editor.kind === 'recurrences' && <><label className="amount-input field"><span>Valor recorrente</span><div><span>R$</span><input autoFocus required inputMode="decimal" value={editor.values.amount} onChange={(event) => field('amount', event.target.value)} placeholder="0,00" /></div></label><label className="field"><span>Descrição</span><input required maxLength={100} value={editor.values.title} onChange={(event) => field('title', event.target.value)} placeholder="Ex.: aluguel, salário, streaming" /></label><Tabs value={editor.values.type} onValueChange={(value) => { field('type', value); field('category', value === 'income' ? 'Salário' : 'Moradia'); field('subcategory', ''); }}><TabsList className="w-full"><TabsTrigger value="expense">Despesa</TabsTrigger><TabsTrigger value="income">Receita</TabsTrigger></TabsList></Tabs><div className="form-grid"><Picker label="Conta ou cartão" value={editor.values.accountId} onChange={(value) => field('accountId', value)} options={state.accounts.map((account) => ({ value: account.id, label: account.name }))} /><Picker label="Frequência" value={editor.values.frequency} onChange={(value) => field('frequency', value)} options={[{ value: 'weekly', label: 'Toda semana' }, { value: 'monthly', label: 'Todo mês' }, { value: 'yearly', label: 'Todo ano' }]} /></div><div className="form-grid"><Picker label="Categoria" value={editor.values.category} onChange={(value) => { field('category', value); field('subcategory', ''); }} options={topLevelCategories(editor.values.type === 'income' ? 'income' : 'expense')} /><label className="field"><span>Primeiro lançamento</span><input type="date" required value={editor.values.nextDate} onChange={(event) => { field('nextDate', event.target.value); field('startDate', event.target.value); }} /></label></div>{subcategoriesFor(editor.values.category).length > 0 && <Picker label="Subcategoria" value={editor.values.subcategory} onChange={(value) => field('subcategory', value)} options={subcategoriesFor(editor.values.category)} allowEmpty />}{state.tags.length > 0 && <TagPicker tags={state.tags} value={editor.values.tags} onChange={(value) => field('tags', value)} />}<label className="field"><span>Repetir até <small>(opcional)</small></span><input type="date" value={editor.values.endDate} onChange={(event) => field('endDate', event.target.value)} /></label><Picker label="Estado" value={editor.values.active} onChange={(value) => field('active', value)} options={[{ value: 'true', label: 'Ativa' }, { value: 'false', label: 'Pausada' }]} /></>}
    {editor.kind === 'accounts' && <><label className="field"><span>Nome da conta ou cartão</span><input autoFocus required maxLength={100} value={editor.values.name} onChange={(event) => field('name', event.target.value)} placeholder="Ex.: conta principal" /></label><Picker label="Tipo" value={editor.values.kind} onChange={(value) => field('kind', value)} options={[{ value: 'checking', label: 'Conta bancária' }, { value: 'cash', label: 'Dinheiro / carteira' }, { value: 'credit', label: 'Cartão de crédito' }]} /><label className="field"><span>{editor.values.kind === 'credit' ? 'Saldo inicial (negativo se houver dívida)' : 'Saldo inicial (R$)'}</span><input required inputMode="decimal" value={editor.values.opening} onChange={(event) => field('opening', event.target.value)} /></label>{editor.values.kind === 'credit' && <><label className="field"><span>Limite do cartão (R$)</span><input required inputMode="decimal" value={editor.values.limit} onChange={(event) => field('limit', event.target.value)} /></label><div className="form-grid"><label className="field"><span>Dia de fechamento</span><input type="number" min="1" max="31" required value={editor.values.closing} onChange={(event) => field('closing', event.target.value)} /></label><label className="field"><span>Dia de vencimento</span><input type="number" min="1" max="31" required value={editor.values.due} onChange={(event) => field('due', event.target.value)} /></label></div></>}<label className="field color-field"><span>Cor de identificação</span><input type="color" value={editor.values.color} onChange={(event) => field('color', event.target.value)} /></label></>}
    {editor.kind === 'budgets' && <><Picker label="Categoria" value={editor.values.category} onChange={(value) => field('category', value)} options={topLevelCategories('expense')} /><label className="field"><span>Limite planejado (R$)</span><input autoFocus required inputMode="decimal" value={editor.values.amount} onChange={(event) => field('amount', event.target.value)} placeholder="Ex.: 600,00" /></label><label className="field"><span>Mês</span><input type="month" required value={editor.values.month} onChange={(event) => field('month', event.target.value)} /></label></>}
    {editor.kind === 'goals' && <><label className="field"><span>Nome da meta</span><input autoFocus required maxLength={100} value={editor.values.name} onChange={(event) => field('name', event.target.value)} placeholder="Ex.: minha reserva de emergência" /></label><div className="form-grid"><label className="field"><span>Quero alcançar (R$)</span><input required inputMode="decimal" value={editor.values.target} onChange={(event) => field('target', event.target.value)} placeholder="10.000,00" /></label><label className="field"><span>Já tenho guardado (R$)</span><input required inputMode="decimal" value={editor.values.saved} onChange={(event) => field('saved', event.target.value)} /></label></div><label className="field"><span>Data do objetivo</span><input type="date" required value={editor.values.date} onChange={(event) => field('date', event.target.value)} /></label><label className="field color-field"><span>Cor da meta</span><input type="color" value={editor.values.color} onChange={(event) => field('color', event.target.value)} /></label></>}
    {editor.kind === 'categories' && <><label className="field"><span>Nome</span><input autoFocus required maxLength={100} value={editor.values.name} onChange={(event) => field('name', event.target.value)} placeholder="Ex.: Pets, Cursos, Renda extra" /></label><Picker label="Tipo" value={editor.values.type} onChange={(value) => { field('type', value); field('parentId', ''); }} options={[{ value: 'expense', label: 'Categoria de saída' }, { value: 'income', label: 'Categoria de entrada' }]} /><Picker label="Categoria pai (opcional)" value={editor.values.parentId} onChange={(value) => field('parentId', value)} options={state.categories.filter((category) => category.type === editor.values.type && !category.parentId).map((category) => ({ value: category.id, label: category.name }))} allowEmpty /><label className="field color-field"><span>Cor</span><input type="color" value={editor.values.color} onChange={(event) => field('color', event.target.value)} /></label></>}
    {editor.kind === 'tags' && <><label className="field"><span>Nome da tag</span><input autoFocus required maxLength={60} value={editor.values.name} onChange={(event) => field('name', event.target.value)} placeholder="Ex.: trabalho, viagem, família" /></label><label className="field color-field"><span>Cor</span><input type="color" value={editor.values.color} onChange={(event) => field('color', event.target.value)} /></label></>}
    {formError && <p role="alert" className="form-error">{formError}</p>}<div className="form-footer"><button type="button" className="secondary-button" disabled={saving} onClick={() => setEditor(null)}>Cancelar</button><button className="primary-button" disabled={saving || ((editor.kind === 'transactions' || editor.kind === 'recurrences') && !state.accounts.length)} type="submit">{saving ? <LoaderCircle className="spin" size={17} /> : <Check size={17} />} {saving ? 'Salvando…' : 'Salvar'}</button></div><p className="form-reassurance"><ShieldCheck size={14} /> Seus registros ficam no seu espaço privado.</p></form>}</DialogContent></Dialog>
  <AlertDialog open={!!deletion} onOpenChange={(open) => { if (!open && !saving) setDeletion(null); }}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Excluir este registro?</AlertDialogTitle><AlertDialogDescription>“{deletion?.name}” será excluído permanentemente. {deletion?.kind === 'transactions' ? 'Se for uma compra parcelada, apenas esta parcela será excluída.' : ''}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={saving}>Cancelar</AlertDialogCancel><AlertDialogAction disabled={saving} onClick={(event) => { event.preventDefault(); void remove(); }}>Excluir registro</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog><Toaster position="bottom-right" richColors /></SidebarProvider>;
}

function TagPicker({ tags, value, onChange }: { tags: Tag[]; value: string; onChange: (value: string) => void }) {
  const selected = new Set(splitIds(value));
  return <div className="field"><span>Tags <small>(opcional)</small></span><div className="tag-picker">{tags.map((tag) => <button type="button" className={`tag-chip ${selected.has(tag.id) ? 'selected' : ''}`} style={{ '--tag-color': tag.color } as CSSProperties} key={tag.id} onClick={() => { const next = new Set(selected); if (next.has(tag.id)) next.delete(tag.id); else next.add(tag.id); onChange([...next].join(',')); }}>{tag.name}</button>)}</div></div>;
}
